var cells=root.querySelectorAll('.trm3-ansi-bars-cell');
var ramp=root.querySelector('.trm3-ansi-bars-blocks');
var seq=root.querySelector('.trm3-ansi-bars-seq');
var nm=root.querySelector('.trm3-ansi-bars-name');
var hx=root.querySelector('.trm3-ansi-bars-hex');
var txt=root.querySelector('.trm3-ansi-bars-txt');
var i=0;
function show(n){
  for(var j=0;j<cells.length;j++){cells[j].classList.remove('trm3-ansi-bars-on');}
  var c=cells[n];if(!c){return;}
  c.classList.add('trm3-ansi-bars-on');
  var h=c.getAttribute('data-h');
  ramp.style.color=h;
  seq.textContent='['+(n>7?'1':'0')+';'+(30+(n%8))+'m';
  nm.textContent=c.getAttribute('data-n');
  hx.textContent=h;
  txt.style.background=h;
  txt.style.color=c.classList.contains('trm3-ansi-bars-dk')?'#000000':'#ffffff';
}
for(var k=0;k<cells.length;k++){(function(n){
  cells[n].addEventListener('mouseenter',function(){i=n;show(n);});
})(k);}
show(0);
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
