var items=root.querySelectorAll('.trm3-bbs-menu-item');
var typed=root.querySelector('.trm3-bbs-menu-typed');
var load=root.querySelector('.trm3-bbs-menu-load');
var order=[1,0,2,7,3,5];
var p=0,timer=null;
function clearOn(){for(var i=0;i<items.length;i++){items[i].classList.remove('trm3-bbs-menu-on');}}
function later(fn,ms){timer=setTimeout(function(){if(!root.isConnected){return;}fn();},ms);}
function pick(el){
  clearOn();
  el.classList.add('trm3-bbs-menu-on');
  typed.textContent=el.getAttribute('data-k');
  load.textContent='» opening '+el.getAttribute('data-l')+' ...';
}
function step(){
  var el=items[order[p%order.length]];
  clearOn();typed.textContent='';load.textContent='';
  later(function(){
    pick(el);
    later(function(){p++;step();},1700);
  },700);
}
for(var i=0;i<items.length;i++){(function(el){
  el.addEventListener('mouseenter',function(){if(timer){clearTimeout(timer);}pick(el);});
  el.addEventListener('mouseleave',function(){p++;step();});
})(items[i]);}
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if(reduce){pick(items[1]);}else{step();}

var lines=root.querySelectorAll('.trm3-dir-list-ln');
var typed=root.querySelector('.trm3-dir-list-typed');
var c1=root.querySelector('.trm3-dir-list-c1');
var cmd='dir *.*';
var timers=[];
function later(fn,ms){var t=setTimeout(function(){if(!root.isConnected){return;}fn();},ms);timers.push(t);return t;}
function reset(){for(var i=0;i<timers.length;i++){clearTimeout(timers[i]);}timers=[];}
function hideAll(){for(var i=1;i<lines.length;i++){lines[i].classList.add('trm3-dir-list-off');}}
function showAll(){for(var i=1;i<lines.length;i++){lines[i].classList.remove('trm3-dir-list-off');}}
function run(){
  reset();hideAll();typed.textContent='';c1.style.visibility='visible';
  var n=0;
  function typeIt(){
    if(n<cmd.length){typed.textContent+=cmd.charAt(n);n++;later(typeIt,95);}
    else{c1.style.visibility='hidden';later(function(){stream(1);},420);}
  }
  later(typeIt,400);
  function stream(i){
    if(i>=lines.length){later(run,3400);return;}
    lines[i].classList.remove('trm3-dir-list-off');
    later(function(){stream(i+1);},i<3?150:190);
  }
}
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if(reduce){typed.textContent=cmd;c1.style.visibility='hidden';showAll();}else{run();}

