var cells=root.querySelectorAll('.trm3-palette-grid-c');
var chip=root.querySelector('.trm3-palette-grid-chip');
var idx=root.querySelector('.trm3-palette-grid-idx');
var lock=root.querySelector('.trm3-palette-grid-lock');
var er=root.querySelector('.trm3-palette-grid-r');
var eg=root.querySelector('.trm3-palette-grid-g');
var eb=root.querySelector('.trm3-palette-grid-b');
var hex=root.querySelector('.trm3-palette-grid-hex');
var i=3,locked=false;
function dac(v){var n=Math.round(parseInt(v,16)/255*63);return (n<10?'0':'')+n;}
function pad(n){return n<10?'00'+n:(n<100?'0'+n:''+n);}
function show(n){
  var c=cells[n];if(!c){return;}
  for(var j=0;j<cells.length;j++){cells[j].classList.remove('trm3-palette-grid-on');}
  c.classList.add('trm3-palette-grid-on');
  var h=c.getAttribute('data-h');
  chip.style.background=h;
  idx.textContent=pad(n);
  er.textContent=dac(h.substr(1,2));
  eg.textContent=dac(h.substr(3,2));
  eb.textContent=dac(h.substr(5,2));
  hex.textContent=h;
}
for(var k=0;k<cells.length;k++){(function(n){
  cells[n].addEventListener('mouseenter',function(){i=n;show(n);});
  cells[n].addEventListener('click',function(){
    locked=!locked;i=n;show(n);
    lock.textContent=locked?'LOCKED':'SCAN';
    if(locked){lock.classList.add('trm3-palette-grid-islock');}else{lock.classList.remove('trm3-palette-grid-islock');}
  });
})(k);}
show(i);
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
lock.textContent=reduce?'READY':'SCAN';
if(!reduce){
  var t=setInterval(function(){
    if(!root.isConnected){clearInterval(t);return;}
    if(locked){return;}
    i=(i+1)%cells.length;show(i);
  },260);
}

