js:
var fill=root.querySelector('.trm3-diskcopy-fill');
var pct=root.querySelector('.trm3-diskcopy-pct');
var file=root.querySelector('.trm3-diskcopy-file');
var note=root.querySelector('.trm3-diskcopy-note');
var spin=root.querySelector('.trm3-diskcopy-spin');
var dn=root.querySelector('.trm3-diskcopy-dn');
var by=root.querySelector('.trm3-diskcopy-by');
var names=['SMARTDRV.EXE','HIMEM.SYS','EMM386.EXE','MSCDEX.EXE','DEFRAG.EXE','SCANDISK.EXE','QBASIC.HLP','DOSSHELL.EXE'];
var sizes=['1,457,664','1,213,952','1,395,712'];
var spins=['|','/','-','\\'];
var p=0,s=0,disk=2,hold=0;
function draw(){
  fill.style.width=p+'%';
  pct.textContent=(p<10?'  ':(p<100?' ':''))+p+'%';
  file.textContent=names[Math.floor(p/100*names.length)%names.length];
}
draw();
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if(reduce){p=53;draw();spin.textContent='-';}
else{
  var t=setInterval(function(){
    if(!root.isConnected){clearInterval(t);return;}
    s=(s+1)%4;spin.textContent=spins[s];
    if(hold>0){hold--;if(hold===0){note.textContent='';note.classList.remove('trm3-diskcopy-flash');p=0;draw();}return;}
    p+=1+Math.floor(Math.random()*3);
    if(p>=100){p=100;hold=18;disk=disk<3?disk+1:1;
      note.textContent='Insert Disk '+disk+' and press ENTER';
      note.classList.add('trm3-diskcopy-flash');
      dn.textContent=disk;by.textContent=sizes[(disk-1)%sizes.length];}
    draw();
  },110);
}

