js:
var free=root.querySelector('.trm3-sysinfo-free2');
var up=root.querySelector('.trm3-sysinfo-up');
var used=root.querySelector('.trm3-sysinfo-used');
var fre=root.querySelector('.trm3-sysinfo-free');
var base=581232,sec=2832;
function comma(n){var s=''+n,o='',c=0;for(var i=s.length-1;i>=0;i--){o=s.charAt(i)+o;c++;if(c%3===0&&i>0){o=','+o;}}return o;}
function two(n){return (n<10?'0':'')+n;}
function paint(){
  var d=base+Math.floor(Math.random()*2400)-1200;
  free.textContent=comma(d);
  var pc=56+Math.round((d-base)/900);
  used.style.flex=''+pc;
  fre.style.flex=''+(91-pc);
  var h=Math.floor(sec/3600),m=Math.floor(sec/60)%60,s=sec%60;
  up.textContent=two(h)+':'+two(m)+':'+two(s);
}
paint();
var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduce){
  var t=setInterval(function(){
    if(!root.isConnected){clearInterval(t);return;}
    sec++;paint();
  },1000);
}
